import os
import json
import numpy as np
import pandas as pd
from fastapi import FastAPI, Query, Body
from pydantic import BaseModel
import mlflow
import mlflow.pyfunc
from mlflow.tracking import MlflowClient

app = FastAPI()

# Set MLflow tracking URI
mlflow.set_tracking_uri("http://127.0.0.1:5000")

# Load the best model from MLflow Model Registry at startup
client = MlflowClient()

# Find the best model in the registry
best_model_name = "breast-cancer-classifier"
best_model_version = None
best_model_info = None

for model in client.list_registered_models():
    if model.name == best_model_name:
        for mv in model.versions:
            if mv.current_stage == "Production":
                best_model_version = mv.version
                best_model_info = {
                    "name": model.name,
                    "version": mv.version,
                    "stage": mv.current_stage
                }
                break

if best_model_version is None:
    raise ValueError(f"Model {best_model_name} not found in Production stage")

# Load the model
loaded_model = mlflow.pyfunc.load_model(
    model_uri=f"models:/{best_model_name}/Production"
)

# Store the loaded model for reuse
# We'll use a module-level variable or a class attribute
# Since FastAPI doesn't support global variables well, we'll use a dependency
# or load it in the route handlers

# For now, let's load it in the route handlers

# Define request and response models

class PredictRequest(BaseModel):
    features: list[float]

class PredictResponse(BaseModel):
    prediction: int
    prediction_label: str
    model_name: str
    model_version: int

class PredictBatchRequest(BaseModel):
    samples: list[list[float]]

class PredictBatchResponse(BaseModel):
    predictions: list[dict]
    count: int
    model_name: str
    model_version: int

class HealthResponse(BaseModel):
    status: str
    model_loaded: bool
    mlflow_tracking_uri: str

class ModelInfoResponse(BaseModel):
    model_name: str
    model_version: int
    model_stage: str
    model_type: str

# Helper function to get model info from MLflow
def get_model_info():
    for model in client.list_registered_models():
        if model.name == best_model_name:
            for mv in model.versions:
                if mv.current_stage == "Production":
                    return {
                        "model_name": model.name,
                        "model_version": mv.version,
                        "model_stage": mv.current_stage,
                        "model_type": "logistic_regression"  # TODO: get from MLflow
                    }
    return None

# Helper function to predict
def predict_single(features):
    # features is a list of 30 floats
    prediction = loaded_model.predict([features])[0]
    prediction_label = "malignant" if prediction == 0 else "benign"
    return {
        "prediction": prediction,
        "prediction_label": prediction_label
    }

# Helper function to predict batch
def predict_batch(samples):
    # samples is a list of lists, each with 30 floats
    predictions = loaded_model.predict(samples)
    results = []
    for i, pred in enumerate(predictions):
        prediction_label = "malignant" if pred == 0 else "benign"
        results.append({
            "prediction": pred,
            "prediction_label": prediction_label
        })
    return results


@app.get("/health")
def health_check():
    return HealthResponse(
        status="healthy",
        model_loaded=True,
        mlflow_tracking_uri="http://127.0.0.1:5000"
    )


@app.get("/model-info")
def model_info():
    model_info = get_model_info()
    if model_info is None:
        raise ValueError(f"Model {best_model_name} not found in Production stage")
    return ModelInfoResponse(
        model_name=model_info["model_name"],
        model_version=model_info["model_version"],
        model_stage=model_info["model_stage"],
        model_type="logistic_regression"
    )


@app.post("/predict")
def predict_endpoint(request: PredictRequest):
    features = request.features
    if len(features) != 30:
        raise ValueError(f"Expected exactly 30 features, got {len(features)}")
    prediction = predict_single(features)
    return PredictResponse(
        prediction=prediction["prediction"],
        prediction_label=prediction["prediction_label"],
        model_name=best_model_name,
        model_version=best_model_version
    )


@app.post("/predict-batch")
def predict_batch_endpoint(request: PredictBatchRequest):
    samples = request.samples
    if not samples:
        raise ValueError("Samples list is empty")
    for sample in samples:
        if len(sample) != 30:
            raise ValueError(f"Sample {sample} has wrong feature count (expected 30, got {len(sample)})")
    predictions = predict_batch(samples)
    return PredictBatchResponse(
        predictions=predictions,
        count=len(predictions),
        model_name=best_model_name,
        model_version=best_model_version
    )


# Load the model at startup
# We'll load it in the on_event handler

@app.on_event("startup")
def load_model():
    global loaded_model, best_model_version
    loaded_model = mlflow.pyfunc.load_model(
        model_uri=f"models:/{best_model_name}/Production"
    )
    # Verify the model can make predictions
    test_sample = [1.0] * 30
    loaded_model.predict([test_sample])


# Wait for the server to start - we'll handle this in the uvicorn command

